#!/usr/bin/env node
// Generates src/generated/* from tokens.json, the single source of the brand
// tokens. `node scripts/build-tokens.mjs` writes the files; `--check` only
// compares and exits 1 when a generated file is out of date.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const HEADER = 'Generated by scripts/build-tokens.mjs from tokens.json. Do not edit.'

const decl = (prefix, obj, indent = '  ') =>
  Object.entries(obj)
    .filter(([k]) => !k.startsWith('$'))
    .map(([k, v]) => `${indent}--bq-${prefix}${k}: ${v};`)
    .join('\n')

/** Everything that is the same in light and dark. */
function scales(t) {
  return [
    decl('', t.palette),
    decl('font-', t.font),
    decl('text-', t.text),
    decl('space-', t.space),
    decl('radius-', t.radius),
    decl('duration-', t.duration),
    decl('ease-', t.ease),
    decl('z-', t.z),
    decl('bar-', t.bar),
  ].join('\n')
}

const mode = (t, m) => [decl('', t.color[m]), decl('shadow-', t.shadow[m])].join('\n')

function css(t) {
  const r = t.restaurant
  const restaurantLight = [decl('', r.light), decl('font-', r.font)].join('\n')
  return `/* ${HEADER} */
:root {
${scales(t)}
${mode(t, 'light')}
}
:root[data-theme='dark'] {
${mode(t, 'dark')}
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
${mode(t, 'dark').replace(/^/gm, '  ')}
  }
}
[data-bq-theme='restaurant'] {
${restaurantLight}
}
:root[data-theme='dark'] [data-bq-theme='restaurant'],
:root[data-theme='dark'][data-bq-theme='restaurant'] {
${decl('', r.dark)}
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) [data-bq-theme='restaurant'],
  :root:not([data-theme])[data-bq-theme='restaurant'] {
${decl('', r.dark, '    ')}
  }
}
`
}

/** booqy.se has one look: light tokens only, whatever <html data-theme> says. */
function lightCss(t) {
  return `/* ${HEADER} Light only, for booqy.se. */
:root {
${scales(t)}
${mode(t, 'light')}
}
`
}

function ts(t) {
  const clean = JSON.parse(JSON.stringify(t, (k, v) => (k.startsWith('$') ? undefined : v)))
  return `// ${HEADER}
export const tokens = ${JSON.stringify(clean, null, 2)} as const

export type ColorToken = keyof typeof tokens.color.light
`
}

/** Emails cannot use CSS variables: flat light values, inlined by the templates. */
function emailValues(t) {
  const flat = {}
  for (const [k, v] of Object.entries(t.palette)) flat[k] = v
  for (const [k, v] of Object.entries(t.color.light)) if (v.startsWith('#')) flat[`color-${k}`] = v
  for (const [k, v] of Object.entries(t.font)) flat[`font-${k}`] = v.replaceAll("'", '')
  for (const [k, v] of Object.entries(t.radius)) flat[`radius-${k}`] = v
  return flat
}

function python(t) {
  const lines = Object.entries(emailValues(t)).map(
    ([k, v]) => `${k.replace(/[^a-z0-9]+/gi, '_').toUpperCase()} = ${JSON.stringify(v)}`,
  )
  return `"""${HEADER}

Booqy brand values for the inline-styled email templates (light only).
Copy this file into application/shared/ (see docs/adr/ADR-BRAND-sharing.md).
"""

${lines.join('\n')}
`
}

export function generate(t) {
  return {
    'src/generated/tokens.css': css(t),
    'src/generated/tokens.light.css': lightCss(t),
    'src/generated/tokens.ts': ts(t),
    'src/generated/email-tokens.json': `${JSON.stringify(emailValues(t), null, 2)}\n`,
    'src/generated/booqy_brand_tokens.py': python(t),
  }
}

export function readTokens() {
  return JSON.parse(readFileSync(join(root, 'tokens.json'), 'utf8'))
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check')
  let stale = 0
  for (const [file, content] of Object.entries(generate(readTokens()))) {
    const path = join(root, file)
    let current = null
    try {
      current = readFileSync(path, 'utf8')
    } catch {
      current = null
    }
    if (current === content) continue
    if (check) {
      console.error(`out of date: ${file} (run npm run tokens)`)
      stale++
    } else {
      mkdirSync(dirname(path), { recursive: true })
      writeFileSync(path, content)
      console.log(`wrote ${file}`)
    }
  }
  process.exit(stale ? 1 : 0)
}
